css:
atom-text-editor,
:host {
  background-color: #141414;
  color: #4e8eab;
}
atom-text-editor .text.html,
:host .text.html {
  color: #939393;
}
atom-text-editor .wrap-guide,
:host .wrap-guide {
  background-color: #2e2e2e;
}
atom-text-editor .indent-guide,
:host .indent-guide {
  color: #2e2e2e;
}
atom-text-editor .invisible-character,
:host .invisible-character {
  color: #2e2e2e;
}
atom-text-editor .gutter,
:host .gutter {
  background-color: #141414;
  color: #616161;
}
atom-text-editor .gutter .line-number.cursor-line,
:host .gutter .line-number.cursor-line {
  background-color: #2e2e2e;
  color: #7a7a7a;
}
atom-text-editor .gutter .line-number.cursor-line-no-selection,
:host .gutter .line-number.cursor-line-no-selection {
  color: #7a7a7a;
}
atom-text-editor .gutter .line-number.folded,
:host .gutter .line-number.folded,
atom-text-editor .gutter .line-number:after,
:host .gutter .line-number:after,
atom-text-editor .fold-marker:after,
:host .fold-marker:after {
  color: #474747;
}
atom-text-editor .invisible,
:host .invisible {
  color: #939393;
}
atom-text-editor .cursor,
:host .cursor {
  color: #939393;
}
atom-text-editor .selection .region,
:host .selection .region {
  background-color: #474747;
}
atom-text-editor .search-results .marker .region,
:host .search-results .marker .region {
  background-color: transparent;
  border: 1px solid #2e2e2e;
}
atom-text-editor .search-results .marker.current-result .region,
:host .search-results .marker.current-result .region {
  border: 1px solid #2e2e2e;
}
.comment {
  color: #616161;
}
.entity.name.type {
  color: #eb7171;
}
.entity.other.inherited-class {
  color: #eb7171;
}
.entity.jade.name.tag {
  color: #4e8eab;
}
.keyword {
  color: #4e8eab;
}
.keyword.control {
  color: #4e8eab;
}
.keyword.operator {
  color: #939393;
}
.keyword.other.special-method {
  color: #4e8eab;
}
.keyword.other.unit {
  color: #eb7171;
}
.keyword.php.control {
  color: #939393;
}
.keyword.python.control {
  color: #939393;
}
.storage {
  color: #939393;
}
.storage.js.function {
  color: #4e8eab;
}
.constant {
  color: #4e8eab;
}
.constant.character.escape {
  color: #eb7171;
}
.constant.numeric {
  color: #eb7171;
}
.constant.other.color {
  color: #4e8eab;
}
.constant.other.symbol {
  color: #eb7171;
}
.variable {
  color: #4e8eab;
}
.variable.interpolation {
  color: #eb7171;
}
.variable.parameter.function {
  color: #939393;
}
.variable.php.variable {
  color: #eb7171;
}
.variable.ruby.variable {
  color: #939393;
}
.invalid.illegal {
  background-color: #eb7171;
  color: #141414;
}
.string {
  color: #eb7171;
}
.string.regexp {
  color: #eb7171;
}
.string.regexp .source.ruby.embedded {
  color: #eb7171;
}
.string.other.link {
  color: #eb7171;
}
.punctuation.definition.comment {
  color: #616161;
}
.punctuation.definition.string,
.punctuation.definition.variable,
.punctuation.definition.parameters,
.punctuation.definition.array {
  color: #939393;
}
.punctuation.definition.heading,
.punctuation.definition.identity {
  color: #4e8eab;
}
.punctuation.definition.bold {
  color: #eb7171;
  font-weight: bold;
}
.punctuation.definition.italic {
  color: #eb7171;
  font-style: italic;
}
.punctuation.definition.json {
  color: #939393;
}
.punctuation.section.embedded {
  color: #eb7171;
}
.punctuation.js.definition.parameters {
  color: #4e8eab;
}
.support.class {
  color: #eb7171;
}
.support.constant {
  color: #eb7171;
}
.support.function {
  color: #4e8eab;
}
.support.function.any-method {
  color: #4e8eab;
}
.entity.name.function {
  color: #4e8eab;
}
.entity.name.class,
.entity.name.type.class {
  color: #4e8eab;
}
.entity.name.section {
  color: #4e8eab;
}
.entity.name.tag {
  color: #eb7171;
  text-decoration: underline;
}
.entity.other.attribute-name {
  color: #eb7171;
}
.entity.other.attribute-name.id {
  color: #4e8eab;
}
.entity.css.name,
.entity.sass.name,
.entity.scss.name {
  text-decoration: none;
}
.entity.html.tag {
  text-decoration: none;
  color: #4e8eab;
}
.entity.jade.tag {
  text-decoration: none;
}
.entity.jade.attribute-name {
  color: #939393;
}
.meta.class {
  color: #4e8eab;
}
.meta.link {
  color: #4e8eab;
}
.meta.require {
  color: #4e8eab;
}
.meta.selector {
  color: #4e8eab;
}
.meta.separator {
  background-color: #adadad;
  color: #939393;
}
.meta.js.delimiter.method {
  color: #939393;
}
.none {
  color: #939393;
}
.markup.bold {
  color: #4e8eab;
  font-weight: bold;
}
.markup.changed {
  color: #eb7171;
}
.markup.deleted {
  color: #eb7171;
}
.markup.italic {
  color: #4e8eab;
  font-style: italic;
}
.markup.heading .punctuation.definition.heading {
  color: #4e8eab;
}
.markup.inserted {
  color: #eb7171;
}
.markup.list {
  color: #eb7171;
}
.markup.quote {
  color: #eb7171;
}
.markup.raw.inline {
  color: #eb7171;
}
.source.gfm .markup {
  -webkit-font-smoothing: auto;
}
.source.gfm .markup.heading {
  color: #eb7171;
}
atom-text-editor[mini] .scroll-view,
:host([mini]) .scroll-view {
  padding-left: 1px;
}
